//: label=wave
//: A sine wave over two periods.
canvas({
  plot.plot(size: (8, 5), x-tick-step: 2, y-tick-step: 0.5, {
    plot.add(domain: (-2*calc.pi, 2*calc.pi), x => calc.sin(x))
  })
})

//: label=rot
//: The rotational field $(-y, x)$.
#import "@preview/cetz:0.3.2"
#import cetz.draw: *

#cetz.canvas({
  for x in range(-2, 3) {
    for y in range(-2, 3) {
      // the field vanishes at the origin, and a zero-length arrow has no
      // direction to point in
      if x != 0 or y != 0 {
        line((x, y), (x - y/4, y + x/4), mark: (end: ">", scale: .4))
      }
    }
  }
})
